export function solve(input) {
    const text = input.text;
    const n = text.length;
    if (n === 0) return 0;

    let maxLength = 0;
    let start = 0;
    const charIndexMap = new Map();

    for (let end = 0; end < n; end++) {
        const currentChar = text[end];

        // If the character is already in the map and its index is not before the current start
        if (charIndexMap.has(currentChar) && charIndexMap.get(currentChar) >= start) {
            // Move the start to one position after the last occurrence of the current character
            start = charIndexMap.get(currentChar) + 1;
        }

        // Update the map with the current character's index
        charIndexMap.set(currentChar, end);

        // Calculate the length of the current substring and update maxLength if necessary
        maxLength = Math.max(maxLength, end - start + 1);
    }

    return maxLength;
}
